FROM shipments
WHERE cost >= 83;

SELECT COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, MIN(cost) AS min_cost, MIN(delivered_date) AS first_delivered_date
FROM shipments
ORDER BY first_delivered_date ASC;

select sum(amount) as total_amount, count(case when status = 'REFUNDED' then 1 end) as refunded_count
from payments
where method in ('cash', 'bank_transfer') and method = 'card';

SELECT DISTINCT dept_name, location
FROM departments
WHERE location NOT IN ('New York', 'Singapore', 'Bangkok');

SELECT s.id, s.start_date, s.plan
FROM subscriptions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE email LIKE '%@mail.co.th');

select supplier_name, city
from suppliers
where rating > 2.0;

SELECT id, segment
FROM customers
WHERE LENGTH(email) < 7;

SELECT id, product_id
FROM inventory
WHERE quantity > 212 AND store_id IN (3, 6);

SELECT *, CONCAT_WS(',', plan, status) AS plan_status_key, DATEDIFF(CURRENT_DATE(), start_date) AS days_since_start_date
FROM subscriptions
WHERE monthly_fee <= 130 AND status = 'EXPIRED' AND status = 'PAUSED';

select *
from (
    select
        method,
        order_id,
        status,
        amount
    from payments
) src
pivot (
    avg(amount) as total
    for status in ('SUCCESS' as success, 'REFUNDED' as refunded)
);

SELECT store_id, quantity, product_id
FROM inventory
WHERE quantity >= 195 OR MONTH(last_restock) IN (4, 9, 11);

select round((100 * sum(case when region = 'East' then 1 else 0 end)) / count(*), 1) as pct_east, max(sqft) as max_sqft
from stores
order by pct_east;

SELECT d.budget, e.level
FROM departments d
LEFT JOIN employees e ON e.dept_id = d.id;

SELECT id, budget, dept_name
FROM departments
WHERE budget >= (SELECT AVG(budget) FROM departments);

select *
from (
    select *, row_number() over (partition by city order by sqft desc, id) as pos
    from stores
) as t
where pos <= 2

SELECT id, store_name, TRIM(region) AS clean_region
FROM stores
WHERE opened_date > '2025-02-12' AND (store_name LIKE '%Downto%' OR region IN ('Central', 'West'));

SELECT paid_at, order_id, UPPER(method) AS method_upper
FROM payments
WHERE paid_at >= '2023-08-22' OR method = 'bank_transfer';

SELECT s.id, s.started_at
FROM sessions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE email LIKE '%@gmail.com');

SELECT id, budget, LEAD(budget, 1) OVER (ORDER BY budget, id) AS next_budget
FROM departments
WHERE dept_name IN ('HR', 'Finance', 'Legal');

SELECT id, event_type, CAST(duration_sec AS STRING) AS duration_sec_num
FROM web_events
ORDER BY id DESC;

select id, order_id, unit_price
from (
    select *, row_number() over (partition by order_id order by unit_price desc, id) as row_num
    from order_items
) as r
where row_num <= 2;

SELECT a.id, a.balance
FROM accounts a
WHERE a.customer_id NOT IN (SELECT id FROM customers WHERE credit_limit <= 8800);

select rating_bucket, new_york_count, num_suppliers
from (
    select case when rating >= 3.8 then 'high' when rating >= 1.5 then 'mid' else 'low' end as rating_bucket, sum(case when city = 'New York' then 1 else 0 end) as new_york_count, count(*) as num_suppliers
    from suppliers
    group by case when rating >= 3.8 then 'high' when rating >= 1.5 then 'mid' else 'low' end
) as sub
where new_york_count >= 80
order by rating_bucket
limit 5;

SELECT o.id, o.status, o.discount
FROM orders o
WHERE o.discount >= 0.18 AND o.customer_id IN (SELECT id FROM customers WHERE is_active);

SELECT id, txn_time, RANK() OVER (ORDER BY txn_time) AS rnk
FROM transactions
WHERE amount BETWEEN 2900 AND 3500;

SELECT s.id, s.store_name
FROM stores s
WHERE EXISTS (SELECT 1 FROM store_sales ss WHERE ss.store_id = s.id);

SELECT id, account_type
FROM accounts
WHERE customer_id IS NOT NULL AND status = 'OPEN' AND opened_date BETWEEN '2024-05-13' AND '2025-09-01';

SELECT * FROM (SELECT session_id, page, duration_sec FROM web_events WHERE session_id IN (23, 25, 28))
PIVOT (COUNT(duration_sec) FOR page IN ('/home', '/search', '/checkout', '/cart'))
ORDER BY session_id;

select * from (select city, region, sqft from stores)
pivot (sum(sqft) for region in ('East', 'West', 'North'))
order by city;

SELECT * FROM (SELECT status, account_type, balance FROM accounts)
PIVOT (SUM(balance) FOR account_type IN ('CHECKING', 'SAVINGS'))
ORDER BY status;

SELECT MONTH(paid_at) AS paid_month, SUM(amount) AS total_amount, ROUND(SUM(amount) * 100.0 / SUM(SUM(amount)) OVER (), 2) AS pct_of_total
FROM payments
GROUP BY MONTH(paid_at);

select
    id,
    store_id,
    sale_date,
    units
from (
    select *, rank() over (partition by store_id, product_id order by sale_date desc nulls first) as latest_rank
    from store_sales
) x
where latest_rank = 1;

select *
from (
    select
        id,
        browser,
        started_at,
        rank() over (partition by browser order by started_at desc) as rnk
    from sessions
) as ranked
where rnk <= 5;

SELECT country, INITCAP(TRIM(country)) country_title
FROM sessions
WHERE customer_id IS NULL OR browser NOT IN ('Firefox', 'Edge');

SELECT product_id, SUM(revenue) AS total_revenue, COUNT(*) AS num_store_sales
FROM store_sales
GROUP BY product_id;

select *
from (
    select *, row_number() over (partition by product_id order by quantity nulls first, id) as row_num
    from inventory
) ranked
where row_num = 1

SELECT s.id, s.country
FROM sessions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE city = 'Bangkok');

SELECT p.id, p.launch_date
FROM products p
WHERE p.launch_date < '2025-05-31' AND p.supplier_id IN (SELECT id FROM suppliers WHERE country IN ('UK', 'TH'));

select id, manager_id
from employees
where dept_id in (8, 19, 29, 39) and salary < 94000;

SELECT s.id, s.cost
FROM shipments s
WHERE s.carrier <> 'Flash' AND s.order_id NOT IN (SELECT id FROM orders WHERE status = 'RETURNED');

SELECT COUNT(DISTINCT price) AS unique_brands
FROM products
WHERE category = 'Books' AND cost BETWEEN 360 AND 580;

select sum(shipping_fee) as total_shipping_fee, min(shipping_fee) as min_shipping_fee
from orders
order by total_shipping_fee;

SELECT hire_date, salary
FROM employees
WHERE manager_id IS NULL;

SELECT country
FROM suppliers
WHERE country IN ('US', 'SG', 'JP') AND (country = 'SG' OR country IN ('JP', 'DE'));

SELECT *
FROM payments
WHERE status IN ('REFUNDED', 'FAILED', 'SUCCESS') AND (status NOT IN ('FAILED', 'REFUNDED') OR order_id = 26);

select last_restock, store_id, case when quantity >= 230 then 'High' when quantity >= 67 then 'Medium' else 'Low' end as quantity_tier
from inventory
where product_id in (5, 10);

SELECT id, amount, RANK() OVER (ORDER BY amount DESC) AS amount_rank
FROM payments
ORDER BY amount_rank DESC, id;

SELECT i.id, i.last_restock, s.opened_date
FROM inventory i
JOIN stores s ON i.store_id = s.id;

SELECT p.id, p.status, o.status AS order_status
FROM payments p
INNER JOIN orders o ON o.id = p.order_id;

SELECT store_id, product_id, SUM(units) AS total_units, AVG(revenue) AS avg_revenue
FROM store_sales
GROUP BY store_id, product_id;

SELECT i.store_id, i.product_id, i.quantity, s.units
FROM inventory i
JOIN store_sales s ON i.store_id = s.store_id AND i.product_id = s.product_id;

SELECT account_id, txn_time, amount,
       SUM(amount) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS running_total
FROM transactions;

SELECT id, sale_date, revenue,
       AVG(revenue) OVER (ORDER BY sale_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7
FROM store_sales;

WITH ranked AS (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, id) AS rn
    FROM employees
)
SELECT * FROM ranked WHERE rn = 1;

SELECT * FROM (
    SELECT segment, country, credit_limit FROM customers
) PIVOT (
    SUM(credit_limit) FOR country IN ('TH', 'US', 'SG')
);
